.purchase-otp-overlay {
  position: fixed;
  inset: 0;
  background: #f9f9f9;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 1rem;
}

.purchase-otp-card {
  background: #ffffff;
  max-width: 420px;
  width: 100%;
  border-radius: 16px;
  box-shadow: 0 6px 24px rgba(0,0,0,0.12);
  padding: 2rem;
  text-align: center;
  font-family: 'Segoe UI', sans-serif;
}

.purchase-otp-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 1rem;
}

.purchase-otp-logo {
  height: 40px;
  float: left;
}

.purchase-otp-text {
  font-size: 1.1rem;
  color: #333;
  margin-bottom: 1.5rem;
  line-height: 1.5;
}

.purchase-otp-input {
  width: 100%;
  padding: 0.75rem;
  border: 1px solid #ddd;
  border-radius: 8px;
  font-size: 1.1rem;
  margin-bottom: 1.5rem;
}

.purchase-otp-actions {
  display: flex;
  gap: 0.5rem;
  justify-content: space-between;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.otp-btn {
  flex: 1;
  padding: 1.3rem 1rem;
  border: none;
  border-radius: 2px;
  font-weight: 600;
  cursor: pointer;
  font-size: 1.1rem;
  transition: 0.3s ease;
  text-transform: uppercase;
}

.otp-btn.confirm {
  background: #3e8b95;
  color: white;
}

.otp-btn.resend {
  background: grey;
  color: white;
}

.otp-btn.cancel {
  background: grey;
  color: white;
}

.purchase-otp-timer {
  font-size: 0.95rem;
  color: #888;
}


@media (max-width: 680px) {
  .purchase-otp-overlay {
    padding: 0;
  }

  .purchase-otp-card {
    border-radius: 0;
    width: 100vw;
    height: 100vh;
    max-width: none;
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding: 2rem 1rem;
  }

  .purchase-otp-actions {
    flex-direction: column;
    gap: 0.75rem;
  }

  .otp-btn {
    width: 100%;
  }
}

.resend-message {
  font-size: 0.85rem;
  color: #219653;
  margin-bottom: 0.5rem;
  animation: fadein 0.3s ease-in;
}

@keyframes fadein {
  from { opacity: 0; }
  to { opacity: 1; }
}