.card-password-popup__overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(6px);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 9999;
}

.card-password-popup__modal {
  background: #fff;
  padding: 2rem;
  border-radius: 18px;
  width: 90%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
  animation: card-popup-scale-in 0.25s ease-in-out;
}

@keyframes card-popup-scale-in {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.card-password-popup__title {
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
  color: #222;
}

.card-password-popup__desc {
  font-size: 0.95rem;
  color: #555;
  margin-bottom: 1.5rem;
}

.card-password-popup__input {
  width: 100%;
  padding: 0.75rem;
  font-size: 1.4rem;
  border: 1.5px solid #ccc;
  border-radius: 10px;
  text-align: center;
  letter-spacing: 6px;
  outline: none;
  margin-bottom: 1.5rem;
}

.card-password-popup__input:focus {
  border-color: #219653;
}

.card-password-popup__actions {
  display: flex;
  justify-content: space-between;
}

.card-password-popup__btn {
  padding: 0.6rem 1.2rem;
  font-size: 0.95rem;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  flex: 1;
  margin: 0 0.5rem;
}

.card-password-popup__btn.cancel {
  background: #eee;
  color: #333;
}

.card-password-popup__btn.submit {
  background: #219653;
  color: white;
}
