.card-type {
  font-size: 1.2rem;
  color: #666;
  margin-top: 0.4rem;
  display: block;
}

.error__CardForm input {
  border: 1px solid red !important;
}
.error__CardForm select {
  border: 1px solid red !important;
}

.error-text__CardForm {
  color: red;
  font-size: 1.2rem;
  margin-top: 0.3rem;
}

.card-form__CardForm{
  background-color: hsl(0, 0%, 96%);
  padding: 1rem;
  border: 1px solid hsl(0, 0%, 87%);
  border-radius: 5px;
}