.security-verify-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  backdrop-filter: blur(6px);
  background-color: rgba(0, 0, 0, 0.4);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 9999;
}

.security-verify-popup {
  background: #fff;
  padding: 2rem 1.5rem;
  border-radius: 18px;
  max-width: 360px;
  width: 90%;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
  text-align: center;
  animation: fadeIn 0.3s ease;
}

.security-verify-icon {
  font-size: 2.5rem;
  color: #219653;
  margin-bottom: 1rem;
}

.security-verify-popup h3 {
  margin: 0;
  font-size: 1.25rem;
  color: #222;
  font-weight: 600;
}

.security-verify-popup p {
  font-size: 0.95rem;
  color: #555;
  margin: 1rem 0 1.5rem;
}

.security-verify-buttons {
  display: flex;
  justify-content: center;
  gap: 1rem;
}

.security-verify-buttons .btn-confirm,
.security-verify-buttons .btn-cancel {
  padding: 0.5rem 1.2rem;
  border: none;
  border-radius: 8px;
  font-size: 0.9rem;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.security-verify-buttons .btn-confirm {
  background-color: #219653;
  color: white;
}

.security-verify-buttons .btn-confirm:hover {
  background-color: #1e874a;
}

.security-verify-buttons .btn-cancel {
  background-color: #f2f2f2;
  color: #333;
}

.security-verify-buttons .btn-cancel:hover {
  background-color: #ddd;
}

@keyframes fadeIn {
  from {
    transform: translateY(10px);
    opacity: 0;
  }
  to {
    transform: translateY(0px);
    opacity: 1;
  }
}


.svp-icons {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.2rem;
  margin-bottom: 1rem;
}

.svp-card-icon {
  height: 20px;
}

.svp-shield-icon {
  font-size: 1.5rem;
  color: #219653;
}
