.payment-popup-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
}

.payment-popup-card {
  background: #fff;
  padding: 2.5rem 2rem;
  border-radius: 20px;
  text-align: center;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
  max-width: 350px;
  width: 90%;
  animation: fadeInPop 0.3s ease-in-out;
  font-family: 'Segoe UI', sans-serif;
}

@keyframes fadeInPop {
  from { transform: scale(0.9); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

.payment-icon {
  margin-bottom: 1rem;
  display: flex;
  justify-content: center;
}

.payment-icon svg {
  stroke-width: 1.2;
}

.payment-icon.success svg {
  color: #27ae60;
}

.payment-icon.failed svg {
  color: #eb5757;
}

.payment-popup-card h2 {
  margin: 0;
  font-size: 1.5rem;
  color: #222;
}

.payment-popup-card p {
  font-size: 0.95rem;
  color: #555;
  margin: 1rem 0 1.5rem;
}

.payment-popup-btn {
  background: #219653;
  color: white;
  padding: 0.75rem 1.5rem;
  border: none;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.3s ease;
}

.payment-popup-btn:hover {
  background: #1a7d45;
}
