.card-brands-container {
  display: flex;
  gap: 8px;
  align-items: center;
  overflow: hidden;
  flex-wrap: nowrap;
}

.card-brand {
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f4f4f4;
  border-radius: 6px;
  width: 46px;
  height: 28px;
  padding: 2px;
  flex-shrink: 0;
  border: 1px solid #ddd;
}

.card-brand img {
  max-width: 100%;
  height: auto;
}

.card-brand.more {
  font-weight: bold;
  background-color: #e0e0e0;
  border: 1px solid #ccc;
  cursor: pointer;
}




.card-icons-wrapper {
  display: flex;
  gap: 0.5rem;
  position: relative;
  align-items: center;
}

.card-icon {
  width: 38px;
  height: 24px;
  object-fit: contain;
}

.more-cards-hover-wrapper {
  position: relative;
  display: inline-block;
}

.more-cards-button {
  background: #f0f0f0;
  border: none;
  padding: 0.15rem 1rem;
  cursor: default;
  border-radius: 4px;
  font-weight: bold;
  font-size: 14px;
}

.more-cards-tooltip {
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(-8px);
  background: black;
  border: 1px solid #ddd;
  padding: 6px;
  border-radius: 4px;
  display: none;
  flex-direction: row;
  gap: 0.5rem;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  z-index: 10;
}

.more-cards-hover-wrapper:hover .more-cards-tooltip {
  display: flex;
  flex-wrap: wrap;
  width: 100%;
  min-width: 150px;
}
