.loading-popup-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  backdrop-filter: blur(6px);
  background-color: rgba(0, 0, 0, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
}

.loading-popup.fancy {
  position: relative;
  background: white;
  padding: 5.5rem 0rem;
  border-radius: 20px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
  text-align: center;
  animation: popupFade 0.3s ease-in-out;
  max-width: 90%;
  width: 300px;
}

@keyframes popupFade {
  from { transform: scale(0.95); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

.dots-loader {
  display: flex;
  justify-content: center;
  align-items: center;
  margin-bottom: 1rem;
}

.dots-loader span {
  width: 10px;
  height: 10px;
  margin: 0 4px;
  background-color: #219653;
  border-radius: 50%;
  animation: bounce 0.6s infinite alternate;
}

.dots-loader span:nth-child(2) {
  animation-delay: 0.2s;
}

.dots-loader span:nth-child(3) {
  animation-delay: 0.4s;
}

@keyframes bounce {
  from { transform: translateY(0); opacity: 0.6; }
  to { transform: translateY(-8px); opacity: 1; }
}

.loading-popup p {
  font-size: 1rem;
  color: #444;
  font-weight: 500;
  margin: 0;
}

.secure-note {
   position: absolute;
  bottom: 1rem;
  left: 0;
  right: 0;

  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 2.5rem;
  font-size: 0.75rem;
  color: #666;
  gap: 0.4rem;
  text-align: center;
  padding: 0 0rem;
}

.secure-icon {
  color: #219653;
  font-size: 0.9rem;
}
